/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 *
 * CONFIGURABLE ASSET LIBRARY — the curated shelf of base models a host can pick
 * up and personalise (per-region colour, per-region finish, an engraved name).
 *
 * Pure data plus pure selectors, following ./starterScenes.ts: no React, no
 * network, no three, so vitest exercises the whole catalogue including every
 * descriptor it ships.
 *
 * ── What is actually IN here, stated plainly ──────────────────────────────
 *
 * `LIBRARY_ASSETS` ships ONE real asset: the baseball cap
 * (`public/models/baseball-cap.glb`, 26,464 verts / 41,141 tris, Meshy-generated
 * then Blender-exported). Its descriptor was authored in `/dev/asset-prep` —
 * regions painted by hand (crown / brim / button), every `refLuminance`
 * MEASURED from the texels that region's UVs cover via the tool's
 * "Measure from texture" pass, and the engraving anchor raycast onto the crown's
 * front panel. `preparedBy: 'human'` is earned, not asserted.
 *
 * `DEMO_LIBRARY_ASSETS` carries the studio's fit-reference bust as a
 * clearly-marked DEV-only entry. It exists so the whole path — pick, recolour,
 * engrave, render through the real booth renderers — can be driven and
 * screenshotted against a second real mesh in development. `libraryAssets()`
 * never returns it outside DEV.
 *
 * ── Adding the next asset ─────────────────────────────────────────────────
 * See LIBRARY_ASSET_CHECKLIST. Short version: a GLB in `public/models/` (or the
 * assets bucket) and a descriptor produced by `/dev/asset-prep`.
 *
 * ── Generic by mandate ────────────────────────────────────────────────────
 * Owner, verbatim: "make sure we remove all the hard-coded templates, like the
 * SCAGO gala or any that have specific branding for any of the legacy events.
 * We're just on generic frames and assets that will be part of the template
 * library that all users will have access to." The colocated test enforces this
 * against a deny-list of legacy tokens, exactly as starterScenes.test.ts
 * enforces it against `BuiltinBorder.legacy` — so branded content cannot arrive
 * here by a later edit either.
 */
import { normalizeTemplate, type AssetTemplate } from './assetTemplate';

/** One shelf entry: a model, its descriptor, and how it reads in the grid. */
export interface ConfigurableAsset {
  id: string;
  name: string;
  /** One line the host reads on the tile — what this is, not how it works. */
  blurb: string;
  /** Two colours for the tile, so it reads at thumbnail size with no image. */
  swatch: [string, string];
  /**
   * The configurator descriptor, as raw data. Deliberately NOT pre-validated:
   * every consumer runs it through `normalizeTemplate`, which is the one place
   * an untrusted descriptor becomes a render spec, and a catalogue that bypassed
   * it would be the one source of templates nobody checked.
   */
  template: unknown;
  /**
   * DEV-only demo content. `libraryAssets()` filters these out of any production
   * build; nothing else in the app reads the flag.
   */
  demo?: boolean;
  /**
   * Authored starting nudge, in head-space CENTIMETRES, applied when the piece
   * is first added — the same `anchorConfig.offset` the Placement sliders edit,
   * so the host can still move it and saved scenes never re-read it. Exists
   * because an anchor centres a model by its bounding box: a cap's box centre
   * sits mid-shell, which parks the brim at eye level; +y lifts it to the
   * hairline. Measured in the live studio, not computed.
   */
  defaultNudgeCm?: { x: number; y: number; z: number };
  /**
   * The head anchor this piece belongs on when added ('noseBridge' for
   * eyewear). Absent = the add-path default (crown), which is right for hats
   * and wrong for a visor. Ignored when `handAnchor` is set.
   */
  anchor?: string;
  /**
   * Hand anchor id (lib/handPose HAND_ANCHORS) — this piece rides the tracked
   * HAND (a wand in the fist, a gauntlet on the wrist), not the head.
   */
  handAnchor?: string;
  /**
   * Authored starting rotation in DEGREES, applied on add. A generated asset's
   * own axes are whatever the generator produced: the gauntlet models a hand
   * held one way, which lands sideways on the wrist anchor until it is turned.
   * Without this the host has to discover three slider values before the piece
   * looks like anything. Measured on a real hand, not computed.
   */
  defaultRotationDeg?: { x: number; y: number; z: number };
  /**
   * Whether the piece should hide behind the head by default. Eyewear wants
   * this (the temples belong behind the face); a necklace or a hand prop does
   * not. Absent = the historical default (off).
   */
  defaultOcclude?: boolean;
}

/**
 * Real-world size of the reference bust along its longest local axis.
 *
 * Measured: the GLB's POSITION accessor spans 1.0835 x 1.5262 x 1.9106 local
 * units, so it is a normalised export and its real size has to be stated rather
 * than read (assetPrep.proposeFitCm returns `confident: true` with exactly that
 * reasoning). 24cm is a human head plus the bust's shoulder base.
 */
const BUST_FIT_CM = 24;

/**
 * The bust is exported with NO materials and NO textures, so three applies the
 * glTF default: an untextured white MeshStandardMaterial whose `diffuseColor`
 * IS its base colour, at a linear luminance of exactly 1.
 *
 * That number is `refLuminance`, and getting it wrong is not cosmetic. It is the
 * DIVISOR: leave it at the 0.18 mid-grey default and every texel divides 1 by
 * 0.18, pegs at MAX_TINT_RATIO and the whole piece renders as a blown-out slab
 * of the requested hue. (FaceRig's `applyRegionTint` carries the same warning
 * from the other side.)
 */
const BUST_REF_LUMINANCE = 1;

/**
 * The DEV-only demo entry.
 *
 * ONE region, no `regionIds`. That is not a simplification — it is the shape a
 * real generated asset actually has. Meshy's remesher emits one watertight
 * manifold (measured: `connectedComponents` on this exact file returns 1), so
 * "the whole piece is region 0" is the honest descriptor for it, and FaceRig
 * supports it explicitly: with no per-vertex attribute every fragment reads
 * region 0 and still gets the bake preserved as relative shading. Multi-region
 * descriptors are authored in `/dev/asset-prep`, which is where the human
 * painting that produces them happens.
 *
 * ── The trap in the numbers below, which cost a wrong first draft ─────────
 * The GLB's single node carries `rotation: [0.7071, 0, 0, 0.7071]` — a +90
 * degree turn about X — so the MESH data is Z-up while the SCENE is Y-up. Every
 * value here is in the MESH's own space, because that is the space
 * `AssetTextSlot.position` lives in: `assetDecal.attachLabelDecal` targets
 * `largestMesh(root)` and `withRestPose` identities that mesh's world matrix
 * before carving, so the node's rotation is not in play.
 *
 * In that space, measured from the POSITION accessor rather than assumed:
 *   · +Y is the FRONT   — the front-most vertex is the nose, at (0, 0.762, −0.07)
 *   · −Z is UP          — the top-most world vertex is the crown, at local z −0.44
 * A bounding box cannot tell you either of those; a slot normal of [0,0,1]
 * looks like the obvious answer and would have engraved the name on the top of
 * the head. (The axes live in the SLOT's normal/up — the render path reads
 * nothing else; a template-level frontAxis field existed and was deleted for
 * having no consumer.)
 *
 * `preparedBy: 'human'` is therefore earned: the axes and the slot were derived
 * from the file's own vertices and confirmed in the running prep tool.
 */
const REFERENCE_BUST_TEMPLATE = {
  id: 'demo-reference-bust',
  name: 'Reference bust',
  glbUrl: '/models/reference-head.glb',
  fitCm: BUST_FIT_CM,
  regions: [
    {
      id: 'surface',
      label: 'Whole piece',
      recolourable: true,
      defaultHex: '#d8d2c8',
      refLuminance: BUST_REF_LUMINANCE,
    },
  ],
  textSlots: [
    {
      id: 'front',
      label: 'Forehead',
      // Probed against the real vertices, not the bounding box: at world-up
      // +0.25 (local z −0.25) the front-most vertex within 6cm of the centre
      // line sits at local y 0.610 — the flat of the forehead above the brow.
      // The bounding-box front (y 0.763) is the NOSE TIP, and a decal projected
      // onto that curve shears (assetDecal note 3).
      position: [0, 0.6, -0.25],
      normal: [0, 1, 0],
      up: [0, 0, -1],
      // 6cm at the bust's 24cm fit is 0.48 model units — inside the ~0.8-unit
      // width of the forehead, so the name does not wrap onto the temples.
      maxWidthCm: 6,
      // 12% of the 1.526-unit FRONT-TO-BACK depth (assetPrep.proposeDecalDepth
      // along the projection axis) — deep enough to reach the surface, shallow
      // enough not to engrave the back of the skull too.
      decalDepth: 0.18,
    },
  ],
  preparedBy: 'human',
} as const;

/* ── the baseball cap ─────────────────────────────────────────────────────── */

/**
 * Per-vertex region ids for the cap, packed by `/dev/asset-prep`
 * (regionTint.packRegionIds): one byte per vertex, base64. The byte VALUE is
 * the index into the template's `regions` array — `buildTemplateDescriptor`
 * guarantees that positional contract even when scaffold regions are dropped.
 * Length decodes to exactly 26,464, the GLB's vertex count; FaceRig degrades to
 * whole-asset styling on any mismatch rather than scrambling parts.
 *
 * Painted by hand in the prep tool (43 strokes), then audited SPATIALLY against
 * the raw position buffer: crown 23,801 verts (the shell, inner surface and
 * strap), brim 2,414 (low, forward, symmetric: y ∈ [−0.45,−0.14], z ∈
 * [0.05,0.95]), button 249 (a tight cluster at the crown apex). The crown/brim
 * boundary was then REFINED analytically (175 seam-band verts reassigned by
 * surface normal — the brim is a horizontal slab, the crown front is steep —
 * plus a majority-smoothing pass), so the seam follows the geometry, not the
 * paint spheres. Ref drift from the swap is bounded at ~0.001 linear: ignored.
 */
const BASEBALL_CAP_REGION_IDS = '';

/**
 * The cap's descriptor, verbatim from `/dev/asset-prep` — only the region
 * labels and `defaultHex` picker seeds were restyled afterwards (the debug
 * palette is for painting, not for hosts).
 *
 * The numbers worth trusting, and why:
 *   · fitCm 26 — the GLB is a normalised export (1.88 units across its longest
 *     axis, brim-to-back); 26cm is an adult cap including the brim.
 *   · front = +z, mesh up +Y — measured from the vertices, not assumed: the
 *     far-+z slab is thin and LOW (y ∈ [−0.395,−0.179]) = the brim, and the
 *     single node carries NO rotation, so mesh space is scene space. This cap
 *     is convention-clean where reference-head.glb is not; the slot's
 *     normal/up carry that orientation into the render.
 *   · refLuminance per region — MEASURED from the albedo texels each region's
 *     UVs cover (crown 1.69M texels, brim 336k, button 10k). The button's bake
 *     really is darker than the crown's (0.205 vs 0.254): a shared value would
 *     recolour it visibly wrong, which is the whole argument for per-region
 *     measurement over the 0.18 placeholder.
 *   · textSlots[0].position — raycast onto the crown's front panel (z 0.4366),
 *     NOT the bounding-box face (z 0.946): the box face is mostly air in front
 *     of a cap, and a decal projected from there needs an absurd depth before
 *     it touches fabric. decalDepth 0.3 reaches the panel's curvature across an
 *     8cm line without cutting the brim below (the projector box's y-extent
 *     stays above the brim plane).
 */
const BASEBALL_CAP_TEMPLATE = {
  id: 'baseball-cap',
  name: 'Baseball cap',
  glbUrl: '/models/baseball-cap.glb',
  fitCm: 26,
  regions: [
    { id: 'crown', label: 'Crown', recolourable: true, defaultHex: '#3d5a80', refLuminance: 0.25437388889761176 },
    { id: 'brim', label: 'Brim', recolourable: true, defaultHex: '#e8e2d6', refLuminance: 0.2783506232996665 },
    { id: 'button', label: 'Button', recolourable: true, defaultHex: '#e8e2d6', refLuminance: 0.20499012263941782 },
  ],
  regionIds: BASEBALL_CAP_REGION_IDS,
  textSlots: [
    {
      id: 'front',
      label: 'Front of the crown',
      position: [-0.0007579922676086426, -0.0015134215354919434, 0.4365548454343863],
      normal: [0, 0, 1],
      up: [0, 1, 0],
      maxWidthCm: 8,
      decalDepth: 0.3,
    },
  ],
  preparedBy: 'human',
} as const;

/**
 * The shipped, host-facing shelf. Add entries here, never to
 * DEMO_LIBRARY_ASSETS.
 */
/* - Cyclops Visor - auto-prepared (src/dev/assetAutoPrep.ts): regions classified
   from the albedo texels under each vertex's UV, refLuminance MEASURED from
   the texture (vertex counts [8696, 16815], region means ['#71152c', '#4b4646']). */
const CYCLOPS_VISOR_TEMPLATE = {
  id: "cyclops-visor",
  name: "Cyclops Visor",
  glbUrl: "/models/cyclops-visor.glb",
  // 16.33, not a round 15: the add path computes anchorConfig.scale as
  // fitScale * fitCm / PROP_TARGET_CM, and 15 landed 7.90 where a real face
  // needs 8.60 (owner-tuned on camera). Authoring the real-world size is what
  // makes a fresh add fit without the host touching a slider.
  fitCm: 16.33,
  // Beam origin: lens-front apex, GLB-local (measured from the lens region's
  // own vertices — centroid x,y pushed to the front surface +2% margin).
  emitter: { position: [0.024, 0.021, 0.984], direction: [0, 0, 1] },
  regions: [
    { id: "lens", label: "Lens", recolourable: true, defaultHex: "#ff2b4a", refLuminance: 0.052903832546146376, guestPick: true },
    { id: "frame", label: "Frame", recolourable: true, defaultHex: "#23262e", refLuminance: 0.0853432732936447 },
  ],
  regionIds:
    "",
  textSlots: [],
  preparedBy: "auto",
} as const;

/* - Wizard Wand - auto-prepared (src/dev/assetAutoPrep.ts): regions classified
   from the albedo texels under each vertex's UV, refLuminance MEASURED from
   the texture (vertex counts [1529, 20460], region means ['#b38dc5', '#59372e']). */
const WIZARD_WAND_TEMPLATE = {
  id: "wizard-wand",
  name: "Wizard Wand",
  glbUrl: "/models/wizard-wand.glb",
  fitCm: 34,
  // Beam origin: the crystal TIP. MEASURED, twice — a whole-mesh PCA reports
  // the shaft along +z, but that axis is flat ribbon/sparkle geometry; the
  // VISIBLE shaft (and both gem crystals) runs along X, and the grip anchor's
  // π/2 z-rotation maps +x to "up out of the fist" — so the business end is
  // the +x gem cluster (535 verts, centroid x 0.909, apex 0.949, y/z ±0.03),
  // pushed just past the crystal surface, firing along +x.
  emitter: { position: [0.968, -0.004, 0.006], direction: [1, 0, 0] },
  regions: [
    { id: "gem", label: "Gem", recolourable: true, defaultHex: "#b388ff", refLuminance: 0.3461678364359895, guestPick: true },
    { id: "shaft", label: "Wood", recolourable: true, defaultHex: "#4a2c17", refLuminance: 0.05376708845871356 },
  ],
  regionIds:
    "",
  textSlots: [],
  preparedBy: "auto",
} as const;

/* - Power Gauntlet - auto-prepared (src/dev/assetAutoPrep.ts): regions classified
   from the albedo texels under each vertex's UV, refLuminance MEASURED from
   the texture (vertex counts [953, 746, 31306], region means ['#5ed5d3', '#a69c6e', '#42413d']). */
const POWER_GAUNTLET_TEMPLATE = {
  id: "power-gauntlet",
  name: "Power Gauntlet",
  glbUrl: "/models/power-gauntlet.glb",
  fitCm: 30,
  // A gauntlet is handed the way a glove is, and this one was generated for a
  // LEFT hand (owner's phone test, 2026-08-04: "Right now, it's left-handed").
  // Declaring it is what lets the render path mirror the mesh for a right hand
  // instead of shipping a second 12 MB GLB — see lib/studio/handedness.ts. The
  // visor and the wand declare nothing, because neither is handed.
  modelledHand: "left" as const,
  // Beam origin: the PALM (−y side — the energy-core disc sits on the back of
  // the hand at +y; this is its mirror through the mesh, nudged just outside
  // the palm skin), firing out of the open palm along −y.
  emitter: { position: [0.026, -0.220, 0.366], direction: [0, -1, 0] },
  regions: [
    { id: "core", label: "Energy core", recolourable: true, defaultHex: "#18ffff", refLuminance: 0.5885494947701743, guestPick: true },
    { id: "trim", label: "Trim", recolourable: true, defaultHex: "#c9a227", refLuminance: 0.38607329178669747 },
    { id: "plating", label: "Plating", recolourable: true, defaultHex: "#2b2e35", refLuminance: 0.08614148964317646 },
  ],
  regionIds:
    "",
  textSlots: [],
  preparedBy: "auto",
} as const;

export const LIBRARY_ASSETS: ConfigurableAsset[] = [
  {
    id: 'baseball-cap',
    name: 'Baseball cap',
    blurb: 'A classic six-panel cap. Crown, brim and button each take their own colour and finish, with a name across the front.',
    swatch: ['#3d5a80', '#e8e2d6'],
    template: BASEBALL_CAP_TEMPLATE,
    defaultNudgeCm: { x: 0, y: 4, z: 0 },
  },
  {
    id: "cyclops-visor",
    name: "Cyclops Visor",
    blurb: "A one-lens hero visor. The lens colour is the blast colour - guests can pick their own in the booth.",
    swatch: ["#23262e", "#ff2b4a"],
    template: CYCLOPS_VISOR_TEMPLATE,
    anchor: 'noseBridge',
    // Owner-tuned against a live face: the visor's box centre sits forward of
    // the lens, so it needs pulling BACK onto the brow rather than pushing out.
    defaultNudgeCm: { x: 0, y: 0.4, z: -6.4 },
    defaultOcclude: true,
  },
  {
    id: "wizard-wand",
    name: "Wizard Wand",
    blurb: "A carved wand with a glowing gem tip, held in the guest's hand. The gem colour drives its sparkle stream.",
    swatch: ["#4a2c17", "#b388ff"],
    template: WIZARD_WAND_TEMPLATE,
    handAnchor: 'grip',
  },
  {
    id: "power-gauntlet",
    name: "Power Gauntlet",
    blurb: "An armored power glove worn on the hand. The energy core colour drives its blast.",
    swatch: ["#2b2e35", "#18ffff"],
    template: POWER_GAUNTLET_TEMPLATE,
    handAnchor: 'wristBack',
    // DERIVED from the mesh, not eyeballed. Measured headlessly over all 33,005
    // vertices: the long PCA axis runs toward the fingers at [0.249,-0.132,0.960]
    // and the palm-outward normal at [0.030,-0.989,-0.143] — which independently
    // agrees with the authored palm emitter firing along GLB -y. Rotating those
    // onto the tracked hand frame (+Y wrist->fingers, +Z out of the palm) gives
    // the Euler below; the earlier hand-tuned values crossed the gauntlet's
    // fingers over the mannequin's by roughly 30 degrees.
    //
    // The NUDGE stays owner-tuned, and that is a finding rather than laziness.
    // Deriving it the same way — put the gauntlet's own wrist (the narrowest
    // cross-section between cuff and hand: 189 vertices at t=-0.461, against
    // 1041 in the cuff and 2606 in the fingers) onto the wrist anchor — gives
    // (0.93, 3.58, -1.17) and renders the gauntlet ~5cm too far up the hand,
    // checked against the mannequin in the orbit view. So one of the two frames
    // this assumes is not what it looks like; until that is measured rather than
    // guessed, the values a human tuned against a real hand win.
    //
    // SIZE is deliberately unchanged: the hand portion measures 1.209 units, so
    // fitCm 30 renders it 19.1cm against an adult mean hand length of 18.6cm —
    // inside 3%, and the owner tuned and accepted that size on a real hand.
    defaultNudgeCm: { x: -0.7, y: -1.9, z: 2.1 },
    defaultRotationDeg: { x: -98.49, y: -14.01, z: -3.78 },
  },
];

/** DEV-only. Never returned by `libraryAssets()` in a production build. */
export const DEMO_LIBRARY_ASSETS: ConfigurableAsset[] = [
  {
    id: 'demo-reference-bust',
    name: 'Reference bust (demo)',
    blurb: 'The studio fit reference, wired up as a configurable asset so the colour and engraving controls can be driven end to end.',
    swatch: ['#d8d2c8', '#4a463f'],
    template: REFERENCE_BUST_TEMPLATE,
    demo: true,
  },
];

/**
 * The shelf, for a given build.
 *
 * `includeDemo` is the caller's `import.meta.env.DEV`, passed IN rather than
 * read here: this module is pure data, a test must be able to ask for both
 * answers, and `import.meta.env` is exactly the kind of ambient global that
 * makes a pure module untestable.
 */
export function libraryAssets(includeDemo = false): ConfigurableAsset[] {
  const shipped = LIBRARY_ASSETS.filter((a) => !a.demo);
  return includeDemo ? [...shipped, ...DEMO_LIBRARY_ASSETS] : shipped;
}

/** An entry's descriptor, validated. Null = the entry is not configurable. */
export function assetTemplateOf(asset: ConfigurableAsset): AssetTemplate | null {
  return normalizeTemplate(asset.template);
}

export function findLibraryAsset(id: string, includeDemo = false): ConfigurableAsset | null {
  return libraryAssets(includeDemo).find((a) => a.id === id) ?? null;
}

/**
 * What an entry needs before it can go in `LIBRARY_ASSETS` — shown verbatim in
 * the dock's empty state, because a host looking at an empty shelf deserves to
 * know it is empty by design and what would fill it.
 */
export const LIBRARY_ASSET_CHECKLIST: readonly string[] = [
  'A .glb of the piece itself — one mesh, ideally 20-40k triangles, in public/models/ or the event assets bucket.',
  'A descriptor from /dev/asset-prep: real-world size, which way it faces, which parts recolour, and where a name is engraved.',
  'A reference luminance measured from the asset\'s own bake — without it a recoloured part renders blown out.',
];

/** The one-line empty state, so the dock and any future surface agree. */
export const LIBRARY_EMPTY_MESSAGE =
  'No configurable models yet. These are base pieces a guest can have in their own colours, with their own name on them.';
